/usr/bin/bash -lc "python - <<'PY'
import json, pathlib
terms=['Naegohyang','AFC Women','Suwon FC Women','Mongwalu','Bunia','Rwampara','Todd Blanche','Saudi Pro League','Al-Nassr','Khalil']
for term in terms:
    print('\\nTERM', term)
    hits=[]
    for path in pathlib.Path('articles').glob('2026/05/15/articles.jsonl'):
        with path.open(errors='ignore') as f:
            for line in f:
                try: a=json.loads(line)
                except Exception: continue
                text=(a.get('title','')+'\\n'+a.get('content',''))
                if term.lower() in text.lower():
                    idx=text.lower().find(term.lower())
                    hits.append((a.get('source'), a.get('title'), text[max(0,idx-400):idx+1200].replace('\\n',' ')))
    print('hits', len(hits))
    for h in hits[:5]:
        print('SRC',h[0],'TITLE',h[1])
        print(h[2])
PY"

